<body class="minhscreen flex itemscenter justifycenter p4 m0 fontsans textwhite"
  style="backgroundcolor: 000; backgroundimage: radialgradient(circle at 50% 50%, 0044cc 0%, 000000 70%); backgroundattachment: fixed;">
  <div class="wfull maxw4xl mxauto selectnone">
    <div
      class="relative flex aspect[1/1.5] wfull itemscenter justifycenter rounded2xl border borderwhite/20 bgblack/40 backdropblurxl sm:aspect[4/3] lg:aspectvideo overflowhidden shadow2xl ring1 ringwhite/10">
      <div id="step1"
        class="absolute inset0 flex itemscenter justifycenter transitionopacity duration500 opacity0">
        <div
          class="flex wfull maxw[90%] flexcol dividey dividewhite/10 overflowhidden rounded3xl border borderwhite/20 bgblack shadow2xl shadowblue900/20 md:maxw2xl md:flexrow md:dividex md:dividey0 backdropblurmd">
          <div class="flex grow flexcol justifybetween gap4 p6">
            <div class="flex size12 itemscenter justifycenter roundedxl border borderwhite/20 bgwhite/10 shadowinner">
              <svg xmlns="" fill="none" viewBox="0 0 24 24"
                strokewidth="1.5" stroke="currentColor" class="w6 h6 textwhite">
                <path strokelinecap="round" strokelinejoin="round"
                  d="M3.75 21h16.5M4.5 3h15M5.25 3v18m13.518v18M9 6.75h1.5m1.5 3h1.5m1.5 3h1.5m36H15m1.5 3H15m1.5 3H15M9 21v3.375c0.621.5041.125 1.1251.125h3.75c.621 0 1.125.504 1.125 1.125V21" />
              </svg>
            </div>
            <div>
              <div class="mb2"><span class="textwhite textxl fontsemibold trackingtight">Foglalási Asszisztens</span></div>
              <div>
                <p class="textneutral400 textsm leadingrelaxed">Ön egy szállodai ügyfélszolgálati munkatárs, aki segít a vendégeknek foglalásokat intézni és általános kérdésekre válaszolni.</p>
              </div>
            </div>
          </div>
          <div class="shrink0 bgwhite/5 p6 md:w[260px]">
            <div class="mb4"><span class="textneutral500 textxs fontsemibold uppercase trackingwider">Elérhető eszközök</span></div>
            <div class="spacey3" id="toollist"></div>
          </div>
        </div>
      </div>

      <div id="chatinterface" class="absolute inset0 flex flexcol p6 transitionopacity duration500 opacity0">
        <div class="relative flex hfull flexcol">
          <div class="grow spacey8">
            <div class="flex justifyend">
              <div
                class="rounded[20px] roundedbrsm bg[0066ff] px5 py3 text[15px] textwhite shadow[0_0_15px_rgba(0,102,255,0.3)] fontmedium trackingtight">
                Szia! Szeretném frissíteni a jelenlegi foglalásomat Executive lakosztályra.
              </div>
            </div>

            <div class="relative h10 wfull md:h6 pl2" id="statuscontainer"></div>

            <div id="userthanks" class="flex justifyend transitionopacity duration300 opacity0">
              <div
                class="rounded[20px] roundedbrsm bg[0066ff] px5 py3 text[15px] textwhite shadow[0_0_15px_rgba(0,102,255,0.3)] fontmedium trackingtight">
                Köszönöm!
              </div>
            </div>
          </div>

          <div class="absolute bottom0 left0">
            <div class="w[220px] shrink0 rounded2xl border borderwhite/20 bgblack/90 backdropblurmd p5 shadowxl">
              <div class="mb3"><span class="textneutral500 textxs fontsemibold uppercase trackingwider">Cselekvési terv</span>
              </div>
              <div class="spacey3" id="planlist"></div>
            </div>
          </div>

          <div class="absolute bottom0 right0 hidden md:flex flexcol itemsend gap4 pointereventsnone"
            id="evalcontainer"></div>
        </div>
      </div>

    </div>
  </div>

  <script>
    const tools = [
      {tag: "clienttool", text: "Vendég keresése email alapján", icon: 'M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5'},
      {tag: "servercode", text: "Foglalási részletek lekérése", icon: 'M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5'},
      {tag: "websearch", text: "Szabad szobák keresése", icon: 'm21 215.1975.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z'},
      {tag: "clienttool", text: "Foglalás módosítása", icon: 'M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5'}
    ];

    const plans = [
      {id: 1, text: "Vendég azonosítása", trigger: 4, done: 5},
      {id: 2, text: "Elérhetőség ellenőrzése", trigger: 6, done: 7},
      {id: 3, text: "Foglalás frissítése", trigger: 8, done: 9}
    ];

    const evals = [
      {step: 5, tag: "clienttool", name: "Vendég keresése email alapján", input: "john.doe@example.com", output: "User ID: 1234567890", icon: 'M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5'},
      {step: 7, tag: "websearch", name: "Szabad szobák keresése", input: "Executive lakosztály", output: "Room ID: 2918482", icon: 'm21 215.1975.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z'},
      {step: 9, tag: "clienttool", name: "Foglalás módosítása", input: "BX23929", output: null, icon: 'M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5'}
    ];

    const toolList = document.getElementById('toollist');
    tools.forEach(t => {
      toolList.innerHTML += 
            <div class="flex itemscenter gap3">
                <div class="flex size9 itemscenter justifycenter roundedlg border borderwhite/10 bgwhite/5">
                    <svg xmlns="" fill="none" viewBox="0 0 24 24" strokewidth="1.5" stroke="currentColor" class="w4 h4 textzinc100">
                        <path strokelinecap="round" strokelinejoin="round" d="${t.icon}" />
                    </svg>
                </div>
                <div class="flex flexcol spacey0.5">
                    <span class="text[10px] textneutral500 fontmono bgwhite/10 px1.5 py0.5 rounded wfit uppercase trackingwide border borderwhite/5">${t.tag}</span>
                    <span class="textzinc300 block textxs fontmedium">${t.text}</span>
                </div>
            </div>;
    });

    function updateUI(step) {
      const step1 = document.getElementById('step1');
      const chatInterface = document.getElementById('chatinterface');
      const statusContainer = document.getElementById('statuscontainer');
      const planList = document.getElementById('planlist');
      const evalContainer = document.getElementById('evalcontainer');
      const userThanks = document.getElementById('userthanks');

      step1.style.opacity = (step === 1) ? "1" : "0";
      chatInterface.style.opacity = (step >= 2) ? "1" : "0";

      let statusHTML = '';
      if (step === 3) statusHTML = '<div class="absolute left0 top0 flex itemscenter gap3 fadeinup"><span class="textzinc400 text[15px]">Rendben, egy pillanat, megkeresem a foglalást...</span></div>';
      else if (step >= 4 && step < 6) statusHTML = '<div class="absolute left0 top0 flex itemscenter gap3 fadeinup"><svg class="w4 h4 textblue500 animatepulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokelinecap="round" strokelinejoin="round" strokewidth="2" d="M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5"/></svg><span class="textzinc200 text[15px] fontmedium">Fiók keresése...</span></div>';
      else if (step >= 6 && step < 8) statusHTML = '<div class="absolute left0 top0 flex itemscenter gap3 fadeinup"><svg class="w4 h4 textblue500 animatepulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokelinecap="round" strokelinejoin="round" strokewidth="2" d="m21 215.1975.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"/></svg><span class="textzinc200 text[15px] fontmedium">Elérhető szobák keresése...</span></div>';
      else if (step >= 8 && step < 10) statusHTML = '<div class="absolute left0 top0 flex itemscenter gap3 fadeinup"><svg class="w4 h4 textblue500 animatepulse" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokelinecap="round" strokelinejoin="round" strokewidth="2" d="M17.25 6.75 22.5 12l5.25 5.25m10.5 0L1.5 12l5.255.25m7.534.5 16.5"/></svg><span class="textzinc200 text[15px] fontmedium">Foglalás frissítése Executive lakosztályra...</span></div>';
      else if (step >= 10) statusHTML = '<div class="absolute left0 top0 flex itemscenter gap3 fadeinup"><span class="textzinc100 text[15px]">Rendben, kész is. A foglalásod mostantól az Executive lakosztályra szól – kellemes pihenést kívánok!</span></div>';
      statusContainer.innerHTML = statusHTML;

      planList.innerHTML = '';
      plans.forEach(p => {
        const isActive = step >= p.trigger && step < p.done;
        const isDone = step >= p.done;
        planList.innerHTML += 
                <div class="flex itemscenter gap3">
                    <div class="relative flex size6 itemscenter justifycenter roundedfull border ${isActive ? 'borderblue500 bgblue500/10' : 'borderwhite/10 bgwhite/5'}">
                        <span class="textxs ${isActive ? 'textblue400 fontbold' : 'textneutral500'}">${p.id}</span>
                        ${isActive ? '<div class="absolute inset0 flex itemscenter justifycenter roundedfull"><svg class="wfull hfull p1 animatespin textblue500" viewBox="0 0 24 24" fill="none"><circle class="opacity25" cx="12" cy="12" r="10" stroke="currentColor" strokewidth="4"></circle><path class="opacity75" fill="currentColor" d="M4 12a8 8 0 0188V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l32.647z"></path></svg></div>' : ''}
                        ${isDone ? '<div class="absolute inset0 flex itemscenter justifycenter roundedfull bgblue600 border borderblue600"><svg class="w3.5 h3.5 textwhite" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokelinecap="round" strokelinejoin="round" strokewidth="2.5" d="m4.5 12.75 6 6 913.5"/></svg></div>' : ''}
                    </div>
                    <div><span class="text[13px] fontmedium transitioncolors ${step >= p.trigger ? 'textwhite' : 'textneutral500'}">${p.text}</span></div>
                </div>;
      });

      evalContainer.innerHTML = '';
      evals.forEach(e => {
        if (step >= e.step) {
          evalContainer.innerHTML += 
                    <div class="transitionall transform opacity100 translatey0">
                        <div class="minw[280px] shrink0 spacey3 rounded2xl border borderwhite/20 bgblack/90 backdropblurmd p4 shadowxl">
                            <div class="flex itemscenter gap3">
                                <div class="flex size8 itemscenter justifycenter roundedlg border borderwhite/10 bgwhite/5">
                                    <svg class="w4 h4 textzinc100" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokelinecap="round" strokelinejoin="round" d="${e.icon}"/></svg>
                                </div>
                                <div class="flex flexcol"><span class="text[10px] textneutral500 fontmono uppercase trackingwide">${e.tag}</span><span class="textzinc100 text[13px] fontmedium">${e.name}</span></div>
                            </div>
                            <div class="spacey2 bgwhite/5 roundedlg p2.5 border borderwhite/5">
                                <div class="flex justifybetween text[11px]"><span class="textneutral500 fontmedium">Bemenet</span><span class="textzinc300 fontmono">${e.input}</span></div>
                                ${e.output ? <div class="h-px bg-white/5 my-1"></div><div class="flex justify-between text-[11px]"><span class="text-neutral-500 font-medium">Kimenet</span><span class="text-blue-400 font-mono">${e.output}</span></div> : ''}
                            </div>
                        </div>
                    </div>;
        }
      });

      userThanks.style.opacity = (step >= 10) ? "1" : "0";
    }

    async function runAnimation() {
      const timings = [2000, 1000, 1000, 800, 800, 800, 800, 800, 800, 3000];
      while (true) {
        for (let i = 1; i <= 10; i++) {
          updateUI(i);
          await new Promise(r => setTimeout(r, timings[i  1]));
        }
        updateUI(0);
        await new Promise(r => setTimeout(r, 500));
      }
    }

    runAnimation();
  </script>

</body>

</html>

